// One item per report: the log window is the 20 minutes before the reported time.
const section = (body, heading) => {
  const m = (body || '').match(new RegExp('###\\s+' + heading + '[^\\n]*\\n+([^#]*)', 'i'));
  const v = m ? m[1].trim() : '';
  return v === '_No response_' ? '' : v;
};
const out = [];
for (const item of $input.all()) {
  const issue = item.json;
  if (issue.pull_request) continue;
  const stamp = Date.parse(section(issue.body, 'Timestamp')) || Date.parse(issue.created_at);
  const report = (section(issue.body, 'Report ID').match(/r-[0-9a-f]{8}/) || [''])[0];
  const from = new Date(stamp - 20 * 60000).toISOString();
  const to = new Date(stamp + 2 * 60000).toISOString();
  out.push({ json: { number: issue.number, url: `http://10.1.0.60:3001/ops/logs?from=${from}&to=${to}${report ? '&report=' + report : ''}` } });
}
return out;

// Keyed by issue number; trimmed so the dispatch payload stays under GitHub's limit.
const windows = $('Log windows').all();
const logs = {};
$input.all().forEach((item, i) => {
  const n = windows[i].json.number;
  const body = item.json || {};
  logs[n] = { report: body.report ?? null, entries: (body.entries || []).slice(-300) };
});
let text = JSON.stringify(logs);
while (text.length > 60000) {
  for (const k of Object.keys(logs)) logs[k].entries = logs[k].entries.slice(Math.ceil(logs[k].entries.length / 3));
  text = JSON.stringify(logs);
}
return [{ json: { logs: text } }];
